133: 	if err != nil {
134: 		return fmt.Sprintf("bad expiry: %q", notAfterString)
135: 	}
136: 
137: 	notBeforeString := annotations[CertificateNotBeforeAnnotation]
138: 	if len(notAfterString) == 0 {
139: 		return "missing notBefore"
140: 	}
141: 	notBefore, err := time.Parse(time.RFC3339, notBeforeString)
142: 	if err != nil {
143: 		return fmt.Sprintf("bad expiry: %q", notBeforeString)
144: 	}
145: 
146: 	// Is cert expired?
147: 	if time.Now().After(notAfter) {
148: 		return "already expired"
149: 	}
150: 
151: 	// Refresh only when expired
152: 	validity := notAfter.Sub(notBefore)
153: 	if validity == refresh {
154: 		return ""
155: 	}
156: 
157: 	// Are we at 80% of validity?
158: 	at80Percent := notAfter.Add(-validity / 5)
159: 	if time.Now().After(at80Percent) {
160: 		return fmt.Sprintf("past its latest possible time %v", at80Percent)
161: 	}
